#!/usr/bin/env bash
# Regenerate TypeScript bindings from crates/protocol.
# Generated files live in apps/desktop/src/shared/ and must not be edited by hand.
set -euo pipefail
cd "$(dirname "$0")/.."
export PATH="${HOME}/.cargo/bin:${PATH}"
export TS_RS_EXPORT_DIR="${PWD}/apps/desktop/src/shared"
rm -f apps/desktop/src/shared/*.ts
cargo test -p protocol --quiet

version="$(grep -oE 'PROTOCOL_VERSION: u32 = [0-9]+' crates/protocol/src/lib.rs | grep -oE '[0-9]+$')"
cat > apps/desktop/src/shared/protocolVersion.ts <<EOF
// @generated by scripts/gen-protocol.sh from crates/protocol/src/lib.rs — do not edit.
export const PROTOCOL_VERSION = ${version} as const
EOF
echo "generated: $(ls apps/desktop/src/shared/*.ts | tr '\n' ' ')"
